      {
        "title": "Security",
        "items": [
          {
            "description": "**Messages router authentication**: all 39 messaging endpoints now require JWT authentication with tutor ownership verification, preventing unauthorized access via spoofed tutor_id parameters"
          },
          {
            "description": "**Parent communications write protection**: POST, PUT, and DELETE endpoints now require authenticated non-read-only users"
          },
          {
            "description": "**Exam revision slot protection**: slot update and delete endpoints now require JWT authentication"
          },
          {
            "description": "**Document processing authentication**: PDF handwriting removal endpoints now require JWT authentication"
          },
          {
            "description": "**Dashboard data protection**: stats, locations, active students, and activity feed endpoints now require authenticated users"
          },
          {
            "description": "**Backend URL hardening**: moved Cloud Run backend URL from source code to environment variable"
          },
          {
            "description": "**Security headers**: added Permissions-Policy (restricts camera, geolocation, payment) and Cross-Origin-Opener-Policy (Spectre protection)"
          },
          {
            "description": "**Request logging**: all API requests now log method, path, status code, and duration for observability"
          },
          {
            "description": "**Explicit Cloud Run settings**: memory, CPU, concurrency, and ingress now set explicitly in deploy config"
          }
        ]
      }
